package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.json.*;

/** Resumable excerpts, explicit request allowance and retained source snapshots. */
final class SummaryWork {
    interface Clients{SeekyAiClient create();}interface Vaults{SeekyAiVault create(Context c);}
    static Clients clients=SeekyAiClient::new;static Vaults vaults=SeekyAiVault::new;
    static void choose(ReaderActivity a){if(!SeekyAiSettings.allowed(a,SeekyAiCore.GEMINI)){PlusUi.toast(a,"Configure primeiro a ligação em Estudar com Seeky.");SeekyAi.reader(a,null);return;}int count=Math.max(1,a.chrome.count()),part=Math.min(count-1,a.chrome.current());LinearLayout form=PlusUi.column(a);EditText first=PlusUi.input(a,a.kind.equals("pdf")?"Da página":"Da parte",""+(part+1),7),last=PlusUi.input(a,a.kind.equals("pdf")?"Até à página":"Até à parte",""+(part+1),7),budget=PlusUi.input(a,"Máximo de pedidos nesta execução (1 a 60)","3",2);for(EditText e:new EditText[]{first,last,budget}){e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);form.addView(e);}form.addView(PlusUi.text(a,"Envia apenas os trechos escolhidos para o Gemini configurado. Consome a quota da sua conta. Ao atingir o limite, a tarefa pausa e pode continuar depois. No fim, os resumos das partes são juntos num resumo geral.",13));new UiDialog.Builder(a).setTitle("Resumo por etapas").setView(form).setPositiveButton("Resumir com Seeky",(d,w)->{try{int start=Integer.parseInt(first.getText().toString())-1,end=Integer.parseInt(last.getText().toString())-1,requests=Integer.parseInt(budget.getText().toString());if(start<0||end<start||end>=count||requests<1||requests>60)throw new IllegalArgumentException("Escolha um intervalo válido e de 1 a 60 pedidos.");enqueue(a,start,end,requests);}catch(Exception e){PlusUi.error(a,e);}}).setNeutralButton("Livro inteiro",(d,w)->{int requests=20;try{requests=Math.max(1,Math.min(60,Integer.parseInt(budget.getText().toString())));}catch(Exception ignored){}if(requests<20)requests=20;enqueue(a,0,count-1,requests);}).setNegativeButton("Cancelar",null).show();}
    static void enqueue(ReaderActivity a,int first,int last,int requests){PlusUi.run(a,()->{String id;try(TaskStore db=new TaskStore(a)){id=db.create("summary","Resumo · "+a.name,new JSONObject().put("uri",a.uri.toString()).put("name",a.name).put("title",a.getIntent().getStringExtra("study_title")==null?a.name:a.getIntent().getStringExtra("study_title")).put("mime",a.mime).put("material",a.getIntent().getLongExtra("study_material",0)).put("first",first).put("last",last).put("whole",first==0&&last==Math.max(1,a.chrome.count())-1).put("requests",requests).put("prepared_part",first).put("english",AppLanguage.english(a)));}final String job=id;TaskService.launch(a,job);});}
    static File root(Context c,String id){if(!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException();File dir=new File(new File(c.getFilesDir(),"work-content"),id);dir.mkdirs();return dir;}
    static void prepare(Context c,StudyStore.Row job,TaskStore work,JSONObject data,TaskService.Control control)throws Exception{String id=job.s("id");if(data.optBoolean("prepared"))return;File dir=root(c,id);Uri uri=Uri.parse(data.getString("uri"));try(SpeechDocument source=new SpeechDocument(c,uri,data.getString("name"),data.getString("mime"),control::cancelled)){int first=data.getInt("first"),last=data.getInt("last");if(first<0||last>=source.count()||last<first)throw new IOException("O intervalo já não está disponível.");int sequence=(int)work.count(id,null);for(int part=data.optInt("prepared_part",first);part<=last;part++){control.check();String text=source.part(part),title=source.partTitle(part,text);List<SeekyAiCore.Slice> slices=SeekyAiCore.slices(text);android.database.sqlite.SQLiteDatabase sql=work.getWritableDatabase();sql.beginTransaction();try{int n=0;for(SeekyAiCore.Slice slice:slices){control.check();String content=text.substring(slice.start,slice.end);if(content.trim().isEmpty())continue;File target=new File(dir,"source-"+sequence+".txt"),temp=new File(dir,"source-"+sequence+".part");try(FileOutputStream out=new FileOutputStream(temp)){out.write(content.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}Files.move(temp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);String label=AppLanguage.text(c,source.kind.equals("pdf")?"Página":"Parte")+" "+(part+1)+" · "+title+" · "+AppLanguage.text(c,"Trecho")+" "+(++n);work.add(id,sequence,uri.toString(),label,target.length(),0);work.item(id,sequence,StudyStore.values("target",target.getPath(),"part",part,"position",slice.start,"material",data.optLong("material")));sequence++;}data.put("prepared_part",part+1).put("partial",data.optBoolean("partial")||source.partial);work.payload(id,data);sql.setTransactionSuccessful();}finally{sql.endTransaction();}control.progress("A preparar trechos · "+(part+1)+" / "+(last+1),0,0);}data.put("prepared",true);work.payload(id,data);work.totals(id);}}
    static String text(Context c,String id,StudyStore.Row item)throws Exception{File file=new File(item.s("target")).getCanonicalFile();if(!DiskWalker.inside(root(c,id).getCanonicalFile(),file)||!file.isFile()||file.length()>60000)throw new IOException("A fonte deste trecho deixou de estar disponível.");return new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}
    static void publish(Context c,String id,TaskStore work,JSONObject data,StudyStore.Row item)throws Exception{if(!item.s("state").equals("done"))return;String tag="Seeky resumo "+id+"_"+item.n("seq");try(StudyStore db=new StudyStore(c)){List<StudyStore.Row> exists=db.rows("notes","tags=?",new String[]{tag},null,1);if(!exists.isEmpty())return;long material=data.optLong("material"),subject=0;StudyStore.Row book=material>0?db.get("materials",material):null;if(book==null)material=0;else subject=book.n("subject");long now=System.currentTimeMillis();String body=item.s("message")+"\n\n"+AppLanguage.text(c,"Fonte")+": "+data.optString("title",data.optString("name"))+" · "+item.s("name")+"\n"+AppLanguage.text(c,"Texto fornecido")+":\n"+AudioTitles.limit(text(c,id,item),2000,6000);db.save("notes",0,StudyStore.values("subject",subject,"material",material,"segment",item.n("part"),"title",AudioTitles.limit("Resumo · "+data.optString("title")+" · "+item.s("name"),200,600),"body",body,"tags",tag,"created",now,"updated",now));}StudyEvents.changed();}
    static void run(Context c,StudyStore.Row job,TaskStore work,TaskService.Control control)throws Exception{if(!SeekyAiSettings.allowed(c,SeekyAiCore.GEMINI))throw new IOException("Configure a ligação em Estudar com Seeky.");String id=job.s("id");JSONObject data=new JSONObject(job.s("payload"));prepare(c,job,work,data,control);String key=vaults.create(c).get(SeekyAiCore.GEMINI);if(key.isEmpty())throw new IOException("Configure a chave pessoal no assistente.");int allowance=Math.max(1,Math.min(60,data.optInt("requests",3))),used=0;
        // Finish local publication of any response committed just before a process interruption.
        int page=0;for(;;){List<StudyStore.Row> done=work.items(id,"done",page,50);for(StudyStore.Row item:done)publish(c,id,work,data,item);if(done.size()<50)break;page+=done.size();}
        while(used<allowance){control.check();List<StudyStore.Row> pending=work.items(id,"pending",0,1);if(pending.isEmpty())break;StudyStore.Row item=pending.get(0);String excerpt=text(c,id,item);int seq=(int)item.n("seq");SeekyAiClient.Call call=new SeekyAiClient.Call();control.interrupt=call::cancel;work.item(id,seq,StudyStore.values("state","sent","message","Pedido enviado; aguarda resposta."));try{
                SeekyAiCore.Result answer=clients.create().ask(SeekyAiCore.GEMINI,key,excerpt,data.optString("title")+" · "+item.s("name"),Collections.emptyList(),data.optBoolean("english")?"Summarise this excerpt in a clear outline. Preserve distinctions and cite the supplied [Tn] sources. Do not claim that you saw other excerpts.":"Resume este trecho com ideias principais e conceitos. Cita as fontes [Tn] fornecidas. Não afirmes ter lido outros trechos.",data.optBoolean("english"),call);
                work.item(id,seq,StudyStore.values("state","done","message",answer.text+(answer.partial?"\n\n"+AppLanguage.text(c,"Resposta parcial do serviço."):"")));item.put("state","done");item.put("message",answer.text+(answer.partial?"\n\n"+AppLanguage.text(c,"Resposta parcial do serviço."):""));publish(c,id,work,data,item);used++;
            }catch(InterruptedIOException e){work.item(id,seq,StudyStore.values("state","uncertain","message","Pedido interrompido. Pode ter consumido quota. Escolha explicitamente se pretende repetir este trecho."));throw e;}
            catch(Exception e){boolean rejected=e instanceof SeekyAiClient.HttpFailure&&((SeekyAiClient.HttpFailure)e).status>=400&&((SeekyAiClient.HttpFailure)e).status<500&&((SeekyAiClient.HttpFailure)e).status!=408;work.item(id,seq,StudyStore.values("state",rejected?"failed":"uncertain","message",rejected?(e.getMessage()==null?"Falha no serviço.":e.getMessage()):"Não foi possível confirmar a resposta. Pode ter consumido quota. Reveja este trecho antes de repetir."));throw e;}finally{control.interrupt=null;}
            long done=work.count(id,"done"),total=work.count(id,null);control.progress(done+" / "+total+" trechos resumidos · "+used+" / "+allowance+" pedidos nesta execução",done,total);
        }
        if(work.count(id,"pending")>0){work.state(id,"paused","Limite de pedidos desta execução atingido. As respostas e fontes foram guardadas. Pode retomar.");control.stopped=true;throw new InterruptedIOException();}
        long uncertain=work.count(id,"uncertain")+work.count(id,"sent");
        // 5.51: once every excerpt is summarised, the summaries are joined (in as many steps as needed) into a general summary.
        if(uncertain==0&&work.count(id,"failed")==0&&work.count(id,"done")>1&&!data.optBoolean("overall_done"))used=overall(c,id,work,data,key,used,allowance,control);
        String message=uncertain>0?"Resumo guardado. Há pedidos interrompidos para rever.":data.optBoolean("overall_done")?"Resumo geral e resumos das partes guardados nos Estudos.":"Resumo e fontes guardados nos Estudos.";work.update(id,StudyStore.values("message",message));control.progress(message,work.count(id,"done"),work.count(id,null));
    }
    static int overall(Context c,String id,TaskStore work,JSONObject data,String key,int used,int allowance,TaskService.Control control)throws Exception{
        boolean english=data.optBoolean("english");String title=data.optString("title",data.optString("name"));List<String> items=new ArrayList<>();JSONArray saved=data.optJSONArray("reduce");
        if(saved!=null)for(int n=0;n<saved.length();n++)items.add(saved.getString(n));
        else{int page=0;for(;;){List<StudyStore.Row> done=work.items(id,"done",page,50);for(StudyStore.Row r:done)items.add(r.s("message"));if(done.size()<50)break;page+=done.size();}}
        while(true){control.check();int need=SeekyAiDeep.groups(items,SeekyAiDeep.GROUP).size();boolean last=need==1;
            if(used+need>allowance){data.put("reduce",new JSONArray(items));work.payload(id,data);work.state(id,"paused","Os resumos das partes estão guardados. Falta juntá-los num resumo geral (cerca de "+SeekyAiDeep.cost(items)+" pedidos). Pode retomar.");control.stopped=true;throw new InterruptedIOException();}
            control.progress(last?"A escrever o resumo geral":"A juntar os resumos das partes",work.count(id,"done"),work.count(id,null));
            final SeekyAiClient.Call call=new SeekyAiClient.Call();control.interrupt=call::cancel;
            try{items=SeekyAiDeep.step(items,title,english,(block,q)->clients.create().askMaterials(SeekyAiCore.GEMINI,key,block,Collections.emptyList(),q,english,call).text);}finally{control.interrupt=null;}
            used+=need;
            if(last){String summary=SeekyAiDeep.clean(items.get(0));data.put("overall",summary).put("overall_done",true);data.remove("reduce");work.payload(id,data);publishOverall(c,id,data,summary);return used;}
            data.put("reduce",new JSONArray(items));work.payload(id,data);
        }
    }
    static void publishOverall(Context c,String id,JSONObject data,String summary)throws Exception{String tag="Seeky resumo geral "+id;try(StudyStore db=new StudyStore(c)){if(!db.rows("notes","tags=?",new String[]{tag},null,1).isEmpty())return;long material=data.optLong("material"),subject=0;StudyStore.Row book=material>0?db.get("materials",material):null;if(book==null)material=0;else subject=book.n("subject");long now=System.currentTimeMillis();String title=data.optString("title",data.optString("name"));String range=data.optInt("first")==0&&data.optBoolean("whole")?AppLanguage.text(c,"livro inteiro"):AppLanguage.text(c,"partes")+" "+(data.optInt("first")+1)+"–"+(data.optInt("last")+1);db.save("notes",0,StudyStore.values("subject",subject,"material",material,"segment",data.optInt("first"),"title",AudioTitles.limit(AppLanguage.text(c,"Resumo geral")+" · "+title,200,600),"body",summary+"\n\n"+AppLanguage.text(c,"Fonte")+": "+title+" ("+range+")","tags",tag,"created",now,"updated",now));}StudyEvents.changed();}
    static void open(Context c,String id){c.startActivity(new Intent(c,SummaryActivity.class).putExtra("job",id));}
    private SummaryWork(){}
}
